// tb_mul_kernels_correctness.sv
//
// Correctness check for the 14 hardware-MUL CPU kernels
// (sim/programs/scheduler/cpu_{dot,matmul}_mul_n*.s, generated by
// scheduler/benchmarks/gen_mul_programs.py) on riscv_soc built with
// ENABLE_MUL=1 -- every dot size's full result and, for each matmul
// size, the first, middle and last output elements. Must pass before any
// of these kernels' cycle counts are trusted.
//
// Expected values computed in Python, not by hand (and emitted into this
// file programmatically, not retyped):
//
//   def dot(n): return sum((i+1)*(i+2) for i in range(n))
//   def matmul(n):
//       A=[[i+j+1 for j in range(n)] for i in range(n)]
//       B=[[i+j+2 for j in range(n)] for i in range(n)]
//       return [sum(A[i][k]*B[k][j] for k in range(n))
//               for i in range(n) for j in range(n)]
//
// matmul output lives at byte 0x3000 = RAM word 0xC00 (3072), as in
// every earlier CPU-only matmul kernel.

`timescale 1ns/1ps

module tb_mul_kernels_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  logic [31:0] g_dot1;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n1.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot1 (`SOC_PORTS(g_dot1));
  logic [31:0] g_dot2;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n2.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot2 (`SOC_PORTS(g_dot2));
  logic [31:0] g_dot3;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n3.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot3 (`SOC_PORTS(g_dot3));
  logic [31:0] g_dot4;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n4.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot4 (`SOC_PORTS(g_dot4));
  logic [31:0] g_dot6;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n6.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot6 (`SOC_PORTS(g_dot6));
  logic [31:0] g_dot8;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n8.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot8 (`SOC_PORTS(g_dot8));
  logic [31:0] g_dot12;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n12.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot12 (`SOC_PORTS(g_dot12));
  logic [31:0] g_dot16;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n16.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot16 (`SOC_PORTS(g_dot16));
  logic [31:0] g_dot32;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n32.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot32 (`SOC_PORTS(g_dot32));
  logic [31:0] g_dot64;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_mul_n64.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_dot64 (`SOC_PORTS(g_dot64));
  logic [31:0] g_mm1;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_mul_n1.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_mm1 (`SOC_PORTS(g_mm1));
  logic [31:0] g_mm2;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_mul_n2.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_mm2 (`SOC_PORTS(g_mm2));
  logic [31:0] g_mm4;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_mul_n4.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_mm4 (`SOC_PORTS(g_mm4));
  logic [31:0] g_mm8;
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_mul_n8.hex"), .RAM_DEPTH_WORDS(4096), .ENABLE_MUL(1'b1))
    dut_mm8 (`SOC_PORTS(g_mm8));

  localparam int MAX_CYCLES = 20000;

  initial begin
    $display("=== hardware-MUL CPU kernel correctness check (ENABLE_MUL=1) ===");
    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;
    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    check("dot N=1 sentinel", g_dot1, 32'hDEADBEEF);
    check("dot N=1 (x20)", dut_dot1.cpu_inst.regfile_inst.regs[20], 32'd2);
    check("dot N=2 sentinel", g_dot2, 32'hDEADBEEF);
    check("dot N=2 (x20)", dut_dot2.cpu_inst.regfile_inst.regs[20], 32'd8);
    check("dot N=3 sentinel", g_dot3, 32'hDEADBEEF);
    check("dot N=3 (x20)", dut_dot3.cpu_inst.regfile_inst.regs[20], 32'd20);
    check("dot N=4 sentinel", g_dot4, 32'hDEADBEEF);
    check("dot N=4 (x20)", dut_dot4.cpu_inst.regfile_inst.regs[20], 32'd40);
    check("dot N=6 sentinel", g_dot6, 32'hDEADBEEF);
    check("dot N=6 (x20)", dut_dot6.cpu_inst.regfile_inst.regs[20], 32'd112);
    check("dot N=8 sentinel", g_dot8, 32'hDEADBEEF);
    check("dot N=8 (x20)", dut_dot8.cpu_inst.regfile_inst.regs[20], 32'd240);
    check("dot N=12 sentinel", g_dot12, 32'hDEADBEEF);
    check("dot N=12 (x20)", dut_dot12.cpu_inst.regfile_inst.regs[20], 32'd728);
    check("dot N=16 sentinel", g_dot16, 32'hDEADBEEF);
    check("dot N=16 (x20)", dut_dot16.cpu_inst.regfile_inst.regs[20], 32'd1632);
    check("dot N=32 sentinel", g_dot32, 32'hDEADBEEF);
    check("dot N=32 (x20)", dut_dot32.cpu_inst.regfile_inst.regs[20], 32'd11968);
    check("dot N=64 sentinel", g_dot64, 32'hDEADBEEF);
    check("dot N=64 (x20)", dut_dot64.cpu_inst.regfile_inst.regs[20], 32'd91520);
    check("matmul N=1 sentinel", g_mm1, 32'hDEADBEEF);
    check("matmul N=1 C[0]", dut_mm1.ram_inst.mem[32'd3072], 32'd2);
    check("matmul N=2 sentinel", g_mm2, 32'hDEADBEEF);
    check("matmul N=2 C[0]", dut_mm2.ram_inst.mem[32'd3072], 32'd8);
    check("matmul N=2 C[2]", dut_mm2.ram_inst.mem[32'd3074], 32'd13);
    check("matmul N=2 C[3]", dut_mm2.ram_inst.mem[32'd3075], 32'd18);
    check("matmul N=4 sentinel", g_mm4, 32'hDEADBEEF);
    check("matmul N=4 C[0]", dut_mm4.ram_inst.mem[32'd3072], 32'd40);
    check("matmul N=4 C[8]", dut_mm4.ram_inst.mem[32'd3080], 32'd68);
    check("matmul N=4 C[15]", dut_mm4.ram_inst.mem[32'd3087], 32'd148);
    check("matmul N=8 sentinel", g_mm8, 32'hDEADBEEF);
    check("matmul N=8 C[0]", dut_mm8.ram_inst.mem[32'd3072], 32'd240);
    check("matmul N=8 C[32]", dut_mm8.ram_inst.mem[32'd3104], 32'd416);
    check("matmul N=8 C[63]", dut_mm8.ram_inst.mem[32'd3135], 32'd1192);

    $display("");
    if (errors == 0) $display("RESULT: ALL CHECKS PASSED");
    else             $display("RESULT: %0d CHECK(S) FAILED", errors);
    $finish;
  end

endmodule
